ANNOTATIONS = [
    (45, 'after', r'''【文件定位】把「在 IDE 里看 diff」接进文件编辑的权限流。用户在 IDE 扩展里查看/修改/保存 diff，终端这边的权限选项随之变成接受或拒绝。核心事实：这个 hook 不等待用户在终端做选择——它把「IDE 里发生的事」翻译成 onChange 的 accept-once/reject。'''),
    (61, 'after', r'''6 位随机 sha 拼进 tab 名，让同一文件的多次 diff 在 IDE 里互不覆盖（每个 diff 一个独立标签页）。'''),
    (65, 'after', r'''tab 名格式：✻ [Claude Code] 文件名 (sha) ⧉。✻ 是 Claude 的星号标记，⧉ 是「外链」符号暗示这是外部工具的标签。'''),
    (72, 'after', r'''三个显示条件全满足才在 IDE 里开 diff：IDE 扩展有 diff 功能（hasAccessToIDEExtensionDiffFeature）、用户配置 diffTool === 'auto'、且不是 .ipynb 文件。文件写入也可能流经这里但不支持 diff，所以排除 notebook。'''),
    (75, 'after', r'''ideName 从已连接的 IDE 客户端名取，取不到回退 'IDE'——对话框里给用户看「在 VS Code 中查看」。'''),
    (90, 'after', r'''showDiffInIDE 是真正的重活：读旧文件、计算打补丁后的内容、调 openDiff RPC、阻塞等用户在 IDE 里的动作。这里 await 它，返回时用户已经在 IDE 里做完了选择。'''),
    (94, 'after', r'''组件卸载后不继续——异步流程可能比 React 组件活得更久，往已卸载组件的 setState 是 React 经典警告来源。'''),
    (105, 'after', r'''newEdits.length === 0 意味着用户在 IDE 里把改动全撤了（或原样保存）——当作拒绝处理。注意这里要主动关标签：注释说「'no' 不再自动关」，所以拒绝路径得自己调 closeTabInIDE。'''),
    (137, 'after', r'''catch 兜底：RPC 失败、IDE 崩了、用户直接关了 IDE 都走这里。setHasError(true) 让 showingDiffInIDE 转 false，终端退回常规权限对话框——IDE 路径失败不能卡住工具调用。'''),
    (148, 'after', r'''空 deps 只在挂载时跑一次。卸载时置 isUnmounted 标志（不是 setState，避免卸载后调 setState）。'''),
    (160, 'after', r'''showingDiffInIDE 对外暴露 = 条件满足且无错误。调用方（权限对话框）据此决定渲染 IDE 提示还是常规选项。'''),
    (199, 'after', r'''computeEditsFromContents 把「用户在 IDE 里看到的」重新翻译成 FileEdit[]。关键点：用户可能在 IDE 里改了新内容（手改补丁内容、格式化、保存），不能拿原始 edits 直接用——必须用 unformatted patch（singleHunk 参数控制），否则二次应用会把 IDE 里的格式改动也吃进去。'''),
    (190, 'after', r'''single 模式却拿到多个 hunk 只记日志不抛错——下游 getEditsForPatch 照样吃，容错优先。'''),
    (202, 'after', r'''【showDiffInIDE 生命周期】四种结束路径：1) 用户在 IDE 关掉标签；2) 用户在 IDE 保存（保存后由本端关标签）；3) 用户在 IDE 里选了选项；4) 用户在终端选选项或按 esc。后两条 abortController 和 cleanup 兜底。三个 TODO 都是已知缺口：5 分钟无活动超时、IDE 退出时更新自动批准 UI、权限提示卸载时关 IDE 标签。'''),
    (232, 'after', r'''旧文件可能不存在（新文件创建场景）——ENOENT 吞掉当空内容，其他错误照抛。'''),
    (251, 'after', r'''cleanup 幂等闸门（isCleanedUp）：这个函数可能从 abort、beforeExit、catch 多处触发，竞态下重复关标签会报错。关标签失败只记日志不抛——清理路径的失败不该盖掉主错误。注销两个监听防泄漏。'''),
    (255, 'after', r'''两条退出触发器：工具调用被 esc 取消（abortController）+ 进程即将退出（beforeExit，用户 ctrl-C 时 IDE 标签不能孤儿化）。'''),
    (264, 'after', r'''getPatchForEdits 算出「应用这些编辑后的完整文件内容」——IDE diff 的右侧就是要展示这个。'''),
    (282, 'after', r'''WSL 路径转换：CLI 跑在 WSL 里而 IDE 在 Windows 上时，路径必须从 /home/... 转成 \\wsl$\... 形式 IDE 才认。三条件全满足才转（本端 wsl + IDE 侧 ideRunningInWindows + 有 WSL_DISTRO_NAME 环境变量）。'''),
    (296, 'after', r'''RPC 结果统一成 ToolCallResponse 数组格式——IDE 扩展返回的可能是单条也可能是数组，下游按数组处理。'''),
    (317, 'after', r'''三种已知结果（FILE_SAVED / TAB_CLOSED / DIFF_REJECTED）之外一律抛 'Not accepted'——用户可能直接关了 IDE，连接断开，走到这里就是状态未知，宁可失败走 catch 关标签，也不要挂着权限提示永远等。'''),
    (343, 'after', r'''closeTabInIDE 吞掉所有错误：这是清理操作，失败也不能影响调用方（连 IDE 都没了的时候尤其如此）。'''),
    (379, 'after_block', r'''三个类型守卫 isClosed/isRejected/isSave 都是防御式结构校验：IDE 扩展是外部进程，RPC 返回的结构不能信——先验证 Array.isArray、每条的 type/text 字段，再收窄类型。save 消息的第二个元素 text 才是用户保存的文件内容。'''),
]
